package dev.tacticalcombat.client.ui;

import com.google.gson.*;
import dev.tacticalcombat.uiapi.SheetSections;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.gui.screen.Screen;
import java.util.*;
import static dev.tacticalcombat.client.ui.ManagementState.*;

/** Existing form and section protocol; each add intent receives one stable ID across retries. */
public final class InventoryForms {
    private InventoryForms() {}
    public static Screen item(Screen parent,JsonObject snapshot,DashboardSource source,JsonObject existing){String id=existing==null?"custom:"+UUID.randomUUID():text(existing,"id");var fields=List.of(field("name","Name",existing,80),new RecordFormScreen.Field("quantity","Quantity",existing==null?"1":text(existing,"quantity"),5),new RecordFormScreen.Field("equipped","Equipped (true/false)",existing==null?"false":text(existing,"equipped"),5),field("slot","Slot",existing,40),new RecordFormScreen.Field("properties","Properties (comma separated)",existing==null?"":String.join(", ",DashboardModel.strings(existing,"properties")),512),field("notes","Description / notes",existing,1024),field("physicalMapping","Minecraft mapping note",existing,128));return new RecordFormScreen(parent,"Equipment details",source.read(),source.readArgs(),fields,(latest,values)->{var inventory=SheetSections.read(latest.getAsJsonObject("sheet"),"inventory");var item=InventoryModel.find(inventory,id);if(item==null){if(existing!=null&&InventoryModel.find(SheetSections.read(snapshot.getAsJsonObject("sheet"),"inventory"),id)!=null)throw new IllegalArgumentException("This item was removed. Refresh your inventory before editing.");item=existing==null?new JsonObject():existing.deepCopy();item.addProperty("id",id);if(!item.has("definition"))item.addProperty("definition","");if(!item.has("properties"))item.add("properties",new JsonArray());}String name=values.get("name").trim();if(name.isEmpty())throw new IllegalArgumentException("Enter an item name.");item.addProperty("name",name);item.addProperty("quantity",WizardEditors.integer(values,"quantity",0,10000));item.addProperty("equipped",Boolean.parseBoolean(values.get("equipped")));item.addProperty("slot",values.get("slot"));String originalProperties=existing==null?"":String.join(", ",DashboardModel.strings(existing,"properties"));if(!values.get("properties").equals(originalProperties))item.add("properties",WizardEditors.array(values.get("properties"),24));item.addProperty("notes",values.get("notes"));item.addProperty("physicalMapping",values.get("physicalMapping"));return source.sectionArgs(latest,"inventory",InventoryModel.upsert(inventory,item));},source.edit(),saved->MinecraftClient.getInstance().setScreen(parent),"Sheet equipment does not grant Minecraft items or change your attacks or armor. Campaign edits may need DM approval again.").expected(snapshot);}
    public static Screen currency(Screen parent,JsonObject snapshot,DashboardSource source){var inventory=SheetSections.read(snapshot.getAsJsonObject("sheet"),"inventory");var fields=new ArrayList<RecordFormScreen.Field>();for(String key:List.of("copper","silver","electrum","gold","platinum"))fields.add(new RecordFormScreen.Field(key,key,text(inventory,key),10));return new RecordFormScreen(parent,"Currency",source.read(),source.readArgs(),fields,(latest,values)->{var data=SheetSections.read(latest.getAsJsonObject("sheet"),"inventory");for(var key:values.keySet())data.addProperty(key,WizardEditors.longNumber(values,key,0,1_000_000_000L));return source.sectionArgs(latest,"inventory",data);},source.edit(),saved->MinecraftClient.getInstance().setScreen(parent),"Currency is kept on the sheet; it does not create Minecraft items.").expected(snapshot);}
    public static Screen catalog(Screen parent,JsonObject snapshot,DashboardSource source){var names=new ArrayList<String>();for(var w:dev.tacticalcombat.rules.srd.SrdEquipment.Weapon.values())if(w!=dev.tacticalcombat.rules.srd.SrdEquipment.Weapon.UNARMED)names.add("Weapon: "+w.name());for(var armor:dev.tacticalcombat.rules.srd.SrdEquipment.Armor.values())if(armor!=dev.tacticalcombat.rules.srd.SrdEquipment.Armor.NONE)names.add("Armor: "+armor.name());return new ChoiceScreen(parent,"SRD equipment",names,s->s.replace('_',' ').toLowerCase(Locale.ROOT),value->{String[] parts=value.split(": ");var item=new JsonObject();item.addProperty("id","custom:"+UUID.randomUUID());item.addProperty("definition","srd:"+(parts[0].equals("Weapon")?"weapon:":"armor:")+parts[1]);item.addProperty("name",parts[1].toLowerCase(Locale.ROOT).replace('_',' '));item.addProperty("quantity",1);item.addProperty("equipped",false);item.addProperty("slot",parts[0].equals("Armor")?"armor":"");var properties=new JsonArray();String description;
        if(parts[0].equals("Weapon")){var weapon=dev.tacticalcombat.rules.srd.SrdEquipment.Weapon.valueOf(parts[1]);weapon.properties.forEach(v->properties.add(v.name()));description="Base damage: "+weapon.dice+"d"+weapon.sides+" "+weapon.damageType.name().toLowerCase(Locale.ROOT)+(weapon.ranged?". Range: "+weapon.normalRangeFeet+" / "+weapon.longRangeFeet+" feet.":".");}else{var armor=dev.tacticalcombat.rules.srd.SrdEquipment.Armor.valueOf(parts[1]);description=armor.kind.name().toLowerCase(Locale.ROOT)+" armor. Base AC "+armor.baseAc+"; Dexterity and requirements follow the 2014 SRD.";}item.add("properties",properties);item.addProperty("notes",description+" SRD 5.1 (2014). Sheet selection does not change combat equipment.");item.addProperty("physicalMapping","");MinecraftClient.getInstance().setScreen(item(parent,snapshot,source,item));});}
    private static RecordFormScreen.Field field(String key,String label,JsonObject item,int limit){return new RecordFormScreen.Field(key,label,item==null?"":text(item,key),limit);}
}
